CREATE TABLE IF NOT EXISTS public.collection_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, installment_id uuid REFERENCES public.installments(id) ON DELETE SET NULL, sale_id uuid REFERENCES public.sales(id) ON DELETE SET NULL, driver_id uuid REFERENCES public.drivers(id) ON DELETE SET NULL, action_type text NOT NULL CHECK (action_type IN ('CALL','SMS','EMAIL','NOTICE','VISIT','PROMISE_TO_PAY','OTHER')), outcome text, notes text, promised_date date, promised_amount numeric, created_by uuid, created_at timestamptz NOT NULL DEFAULT now());